$ErrorActionPreference = "Stop"
if (-not (Test-Path "backend\src\jobs")) { Write-Host "Ejecuta este script desde la raiz del repo (carpeta Contratos)." -ForegroundColor Red; exit 1 }
$b = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "backend\src\utils\reporteMensualArrendamientos.js"), [Convert]::FromBase64String($b))
Write-Host "OK" -ForegroundColor Green
Write-Host "Ahora: git add -A; git commit -m Copia permanente del reporte de Arrendamientos; git push" -ForegroundColor Green